//! Read-model projections resolved directly in the database.
//!
//! A [`Response`] describes how an API payload is built from its table
//! *inside* SurrealDB: instead of loading an entity and then fetching every
//! related row (the classic N+1), the projection nests the relations in a
//! single `SELECT VALUE { ... }` query.
//!
//! The projection is usually generated by `#[derive(Response)]`; the
//! repository only calls the read helpers in
//! [`crate::db::query`](crate::db::query) which reuse it.

/// A response that knows how to project itself from its table.
pub trait Response {
    /// The table the response is read from.
    const TABLE: &'static str;

    /// The SurrealQL projection body (the fields between `{` and `}`), with
    /// scalars and relations already resolved. It never contains user input:
    /// it is a compile-time constant.
    fn projection() -> String;

    /// The projection wrapped in braces, ready to be interpolated in a
    /// `SELECT VALUE { ... }` query.
    fn select_fields() -> String {
        format!("{{ {} }}", Self::projection())
    }
}
